begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
select ok(not has_column_privilege('authenticated','public.workout_movements','suggested_intent','UPDATE'),'intent input is immutable');
select ok(not has_column_privilege('authenticated','public.workout_movements','slot_snapshot','INSERT'),'snapshot stays derived');
select ok(not has_function_privilege(r,'public.movement_intent(text)','EXECUTE'),'no registry RPC privilege for '||r) from unnest(array['anon','service_role'])r;
insert into auth.users(id,email_confirmed_at) values (md5('intent_a')::uuid,clock_timestamp()),(md5('intent_b')::uuid,clock_timestamp());
insert into profiles(id,display_name) values(md5('intent_a')::uuid,'Intent A'),(md5('intent_b')::uuid,'Intent B');
insert into account_preferences(owner_id) values(md5('intent_a')::uuid),(md5('intent_b')::uuid);
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',md5('intent_a')::uuid,'role','authenticated')::text,true);
select is(public.movement_intent('invented'),null::jsonb,'unknown intent never creates fabricated mechanics');
select set_config('body_test.three',(select jsonb_agg(jsonb_build_object('intent',k,'pattern',d->>'patternId','muscle',d->>'muscleId','exerciseType',d->>'exerciseType','title',d->>'title') order by k)::text from unnest(array['standard_curl','neutral_curl','lengthened_curl'])k cross join lateral public.movement_intent(k)d),true);
select set_config('body_test.w',start_suggested_workout(current_setting('body_test.three')::jsonb,md5('three_curls')::uuid)::text,true);
select is((select count(*)::int from workout_movements where workout_session_id=current_setting('body_test.w')::uuid),3,'three distinct curl intents share one primary pattern');
select is((select count(distinct suggested_pattern_id)::int from workout_movements where workout_session_id=current_setting('body_test.w')::uuid),1,'no invented pattern IDs');
select is((select count(distinct slot_snapshot->>'intent')::int from workout_movements where workout_session_id=current_setting('body_test.w')::uuid),3,'each saved snapshot retains its precise intent');
select is((select count(*)::int from workout_exercises where workout_session_id=current_setting('body_test.w')::uuid),0,'no exercises chosen by generation');
select is(start_suggested_workout(current_setting('body_test.three')::jsonb,md5('three_curls')::uuid),current_setting('body_test.w')::uuid,'start is idempotent');
select set_config('body_test.m',(select id::text from workout_movements where workout_session_id=current_setting('body_test.w')::uuid and suggested_intent='neutral_curl'),true);
select set_config('body_test.e',select_program_exercise(current_setting('body_test.m')::uuid,(select id from exercises where slug='dumbbell_hammer_curl'),null,md5('intent_select')::uuid)::text,true);
select ok((select bool_and(actual_reps is null and actual_weight_kg is null and effort_value is null and not inputs_confirmed and status='pending' and not performed_to_failure and prescribed_reps_min=10) from workout_sets where workout_exercise_id=current_setting('body_test.e')::uuid),'normal logger suggestions preserve blank actuals, effort and weights');
select lives_ok($$select end_workout(current_setting('body_test.w')::uuid,'abandoned')$$,'close curl workout');
select throws_ok($$select start_suggested_workout(current_setting('body_test.three')::jsonb||jsonb_build_array(current_setting('body_test.three')::jsonb->0),md5('duplicate_intent')::uuid)$$,'22023',null,'duplicate intent rejected');
select throws_ok($$select start_suggested_workout(jsonb_build_array(jsonb_set(current_setting('body_test.three')::jsonb->0,'{intent}','"invented"')),md5('forged_intent')::uuid)$$,'22023',null,'forged intent rejected');
select throws_ok($$select start_suggested_workout(jsonb_build_array(jsonb_set(current_setting('body_test.three')::jsonb->0,'{intent}','"flat_press"')),md5('mismatched_intent')::uuid)$$,'22023',null,'wrong pattern/muscle/type intent rejected');
select set_config('body_test.six',(select jsonb_agg(jsonb_build_object('intent',k,'pattern',d->>'patternId','muscle',d->>'muscleId','exerciseType',d->>'exerciseType','title',d->>'title') order by k)::text from unnest(array['squat','hinge','single_leg','leg_curl','calf_straight','calf_bent'])k cross join lateral public.movement_intent(k)d),true);
select set_config('body_test.w6',start_suggested_workout(current_setting('body_test.six')::jsonb,md5('six_intents')::uuid)::text,true);
select is((select count(*)::int from workout_movements where workout_session_id=current_setting('body_test.w6')::uuid),6,'six automatically generated slots are allowed');
select set_config('body_test.extra',(select jsonb_build_object('intent','hip_thrust','pattern',d->>'patternId','muscle',d->>'muscleId','exerciseType',d->>'exerciseType','title',d->>'title')::text from public.movement_intent('hip_thrust')d),true);
select set_config('body_test.edit',edit_suggested_movement(current_setting('body_test.w6')::uuid,md5('seventh_manual')::uuid,current_setting('body_test.extra')::jsonb)::text,true);
select is((select count(*)::int from workout_movements where workout_session_id=current_setting('body_test.w6')::uuid),7,'manual movement additions are independent of automatic cap');
select is(edit_suggested_movement(current_setting('body_test.w6')::uuid,md5('seventh_manual')::uuid,current_setting('body_test.extra')::jsonb),current_setting('body_test.edit')::uuid,'intent edit retry is stable');
select throws_ok($$select edit_suggested_movement(current_setting('body_test.w6')::uuid,md5('seventh_manual')::uuid,current_setting('body_test.extra')::jsonb-'intent')$$,'23514',null,'edit retry binds intent metadata');
select set_config('request.jwt.claims',json_build_object('sub',md5('intent_b')::uuid,'role','authenticated')::text,true);
select is((select count(*)::int from workout_movements where workout_session_id=current_setting('body_test.w6')::uuid),0,'other owner cannot read refined intents');
select throws_ok($$select edit_suggested_movement(current_setting('body_test.w6')::uuid,md5('foreign_intent')::uuid,current_setting('body_test.extra')::jsonb)$$,'42501',null,'other owner cannot add refined intent');
select set_config('request.jwt.claims',json_build_object('sub',md5('intent_a')::uuid,'role','authenticated')::text,true);
select lives_ok($$select end_workout(current_setting('body_test.w6')::uuid,'abandoned')$$,'close six-slot workout');
select throws_ok($$select start_suggested_workout(current_setting('body_test.six')::jsonb||jsonb_build_array(current_setting('body_test.extra')::jsonb),md5('seven_auto')::uuid)$$,'22023',null,'automatic starts cannot exceed six');
select throws_ok($$select edit_suggested_movement(current_setting('body_test.w6')::uuid,md5('closed_intent')::uuid,current_setting('body_test.extra')::jsonb)$$,'23514',null,'closed workout still rejects mutations');
select * from finish();rollback;
